SELECT DATE(usage_start_time,'Europe/Istanbul') day, service.description service, c.type credit_type, c.name credit_name, SUM(c.amount) credit_try FROM `project-27082a40-6083-4952-9db.billing_export.gcp_billing_export_resource_v1_017786_B62E9C_E21182`,UNNEST(credits) c WHERE (_PARTITIONTIME >= TIMESTAMP('2026-10-31') OR _PARTITIONTIME IS NULL) AND usage_start_time >= TIMESTAMP('2026-11-01 00:00:00+03') AND usage_start_time < CURRENT_TIMESTAMP() AND project.id='project-27082a40-6083-4952-9db' GROUP BY day,service,credit_type,credit_name ORDER BY day,credit_try